--

LOCK TABLES `credit_wallet_statement` WRITE;
/*!40000 ALTER TABLE `credit_wallet_statement` DISABLE KEYS */;
/*!40000 ALTER TABLE `credit_wallet_statement` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `fin_account`
--

DROP TABLE IF EXISTS `fin_account`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fin_account` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '账户ID（主键）',
  `user_id` bigint NOT NULL COMMENT '所属用户ID（系统用户表 fk）',
  `account_code` varchar(64) NOT NULL COMMENT '系统内部唯一编码（格式：ACCT-{userId}-{seq}）',
  `account_name` varchar(128) NOT NULL COMMENT '账户可读名，如：宁波信用卡(尾号1234)、微信余额',
  `account_category` varchar(32) NOT NULL COMMENT '账户大类：CASH/CLEARING/INVEST/BENEFIT/TRANSIT/LEDGER',
  `account_type` varchar(32) NOT NULL COMMENT '细分类：BANK_CARD/E_WALLET/CREDIT/BROKER_FUND/FUND_TA/STOCK_POSITION/COUPON/SUBSIDY',
  `owner_type` varchar(16) DEFAULT 'USER' COMMENT '账户所有者类型：USER/PLATFORM/MERCHANT/SYSTEM',
  `platform_code` varchar(64) DEFAULT NULL COMMENT '外部机构/平台代码：WECHAT/ALIPAY/MEITUAN/CMB/TONGHUASHUN 等',
  `currency` varchar(10) DEFAULT 'CNY' COMMENT '币种',
  `balance` decimal(18,2) DEFAULT '0.00' COMMENT '当前余额（冗余字段，由流水同步）',
  `balance_updated_at` datetime DEFAULT NULL COMMENT '余额最后更新时间',
  `external_account_ref` varchar(128) DEFAULT NULL COMMENT '外部账户标识（卡号尾号/账号/OpenID等，用于去重）',
  `is_virtual` tinyint(1) DEFAULT '0' COMMENT '是否虚拟账户（1=虚拟，如补贴池；0=真实银行/券商）',
  `status` varchar(16) DEFAULT 'ACTIVE' COMMENT '状态：ACTIVE/INACTIVE/FROZEN',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注字段',
  `created_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(64) DEFAULT NULL COMMENT '最近修改人',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近修改时间',
  `is_deleted` tinyint DEFAULT '0' COMMENT '是否删除（0-否，1-是）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `account_code` (`account_code`),
  UNIQUE KEY `uk_user_platform_ref` (`user_id`,`platform_code`,`external_account_ref`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_platform_code` (`platform_code`),
  KEY `idx_account_category` (`account_category`)
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='账户主表：描述资金容器（银行/钱包/券商/补贴等）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `fin_account`
--

