CREATE TABLE `fin_statement` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '账单行ID',
  `file_id` bigint NOT NULL COMMENT 'fin_statement_file.id',
  `user_id` bigint NOT NULL COMMENT '所属用户',
  `platform_code` varchar(64) NOT NULL COMMENT '来源平台：WECHAT/ALIPAY/CMB/MEITUAN/TIKTOK/OTHER',
  `source_type` varchar(32) DEFAULT NULL COMMENT '细分类：PLATFORM_ORDER/BANK_STATEMENT/CREDIT_CARD_STATEMENT/SECURITIES_TRADE',
  `raw_row_hash` char(32) DEFAULT NULL COMMENT '行级幂等Hash（md5(file_id + row_raw)）',
  `raw_data` json DEFAULT NULL COMMENT '原始或解析后的行 JSON（完整）',
  `out_trade_no` varchar(128) DEFAULT NULL COMMENT '平台订单号/流水号（若有）',
  `stmt_time` datetime DEFAULT NULL COMMENT '账单行时间（原始时间）',
  `amount` decimal(18,2) DEFAULT NULL COMMENT '金额（正入/负出或用 direction 字段）',
  `direction` varchar(8) DEFAULT NULL COMMENT 'IN/OUT',
  `counterparty` varchar(128) DEFAULT NULL COMMENT '对方/商户（美团/拼多多/招商银行）',
  `account_ref` varchar(128) DEFAULT NULL COMMENT '原始文本中指示的账户（用于初步映射，如 卡号尾号/支付宝账号）',
  `description` varchar(255) DEFAULT NULL COMMENT '交易摘要/备注',
