  `parser_version` varchar(32) DEFAULT NULL COMMENT '解析器版本号（便于重解析）',
  `retry_count` int DEFAULT '0' COMMENT '重试次数',
  `parsed_at` datetime DEFAULT NULL COMMENT '解析完成时间',
  `status` varchar(16) DEFAULT 'NEW' COMMENT 'NEW/PARSED/MAPPED/IGNORED',
  `created_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(64) DEFAULT NULL COMMENT '最近修改人',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近修改时间',
  `is_deleted` tinyint DEFAULT '0' COMMENT '是否删除（0-否，1-是）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_file_row` (`file_id`,`raw_row_hash`),
  KEY `idx_user_platform_time` (`user_id`,`platform_code`)
) ENGINE=InnoDB AUTO_INCREMENT=428 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='账单行表：保存每一行原始/解析后数据，作为证据';
