  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近修改时间',
  `is_deleted` tinyint DEFAULT '0' COMMENT '是否删除（0-否，1-是）',
  PRIMARY KEY (`id`),
  KEY `idx_platform_source` (`platform_code`,`source_type`,`enabled`),
  KEY `idx_target_type` (`target_type`)
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='账单映射规则表：用于配置化管理各平台账单字段到内部模型的映射规则';
