--
-- Table structure for table `fin_transaction`
--

DROP TABLE IF EXISTS `fin_transaction`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fin_transaction` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '交易ID（业务中枢）',
  `user_id` bigint NOT NULL COMMENT '所属用户',
  `transaction_no` varchar(64) NOT NULL COMMENT '系统交易号/业务流水号',
  `biz_type` varchar(32) NOT NULL COMMENT '业务类型：PAY/TRANSFER/INVEST/REDEEM/REPAY/REFUND',
  `biz_sub_type` varchar(64) DEFAULT NULL COMMENT '子类型，如：CREDIT_PAY/BALANCE_PAY/FUND_SUBSCRIBE/STOCK_BUY',
  `category_id` bigint DEFAULT NULL COMMENT '交易分类ID（关联 transaction_category）',
  `trade_time` datetime NOT NULL COMMENT '交易发生时间（业务时间）',
  `amount` decimal(18,2) NOT NULL COMMENT '业务金额（通常为总额）',
  `currency` varchar(10) DEFAULT 'CNY' COMMENT '币种',
  `status` varchar(32) DEFAULT 'INIT' COMMENT '业务状态：INIT/MATCHED/CONFIRMED/CANCELLED',
  `counterparty` varchar(128) DEFAULT NULL COMMENT '交易对手或商户名称（美团/拼多多/同花顺）',
  `platform_code` varchar(64) DEFAULT NULL COMMENT '来源平台：MEITUAN/WECHAT/ALIPAY/TIKTOK/NINGBO_BANK',
  `original_transaction_id` bigint DEFAULT NULL COMMENT '原交易ID（退款时指向原单）',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注/摘要',
  `created_by` varchar(64) DEFAULT NULL COMMENT '创建人（系统/解析器/人工）',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(64) DEFAULT NULL COMMENT '修改人',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `is_deleted` tinyint DEFAULT '0' COMMENT '是否删除（0-否，1-是）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `transaction_no` (`transaction_no`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_user_time` (`user_id`,`trade_time`),
  KEY `idx_platform_code` (`platform_code`),
  KEY `idx_category_id` (`category_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='交易中枢表：表示一笔业务事实（消费/投资/还款等）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `fin_transaction`
--

LOCK TABLES `fin_transaction` WRITE;
/*!40000 ALTER TABLE `fin_transaction` DISABLE KEYS */;
